private static SchemaApi.FieldType fieldTypeToProto(FieldType fieldType,boolean serializeLogicalType){
  SchemaApi.FieldType.Builder builder=SchemaApi.FieldType.newBuilder();
switch (fieldType.getTypeName()) {
case ROW:    builder.setRowType(SchemaApi.RowType.newBuilder().setSchema(schemaToProto(fieldType.getRowSchema(),serializeLogicalType)));
  break;
case ARRAY:builder.setArrayType(SchemaApi.ArrayType.newBuilder().setElementType(fieldTypeToProto(fieldType.getCollectionElementType(),serializeLogicalType)));
break;
case ITERABLE:builder.setIterableType(SchemaApi.IterableType.newBuilder().setElementType(fieldTypeToProto(fieldType.getCollectionElementType(),serializeLogicalType)));
break;
case MAP:builder.setMapType(SchemaApi.MapType.newBuilder().setKeyType(fieldTypeToProto(fieldType.getMapKeyType(),serializeLogicalType)).setValueType(fieldTypeToProto(fieldType.getMapValueType(),serializeLogicalType)).build());
break;
case LOGICAL_TYPE:LogicalType logicalType=fieldType.getLogicalType();
SchemaApi.LogicalType.Builder logicalTypeBuilder;
String identifier=logicalType.getIdentifier();
boolean isStandard=STANDARD_LOGICAL_TYPES.containsKey(identifier);
if (!isStandard && logicalType instanceof UnknownLogicalType) {
logicalTypeBuilder=SchemaApi.LogicalType.newBuilder().setUrn(logicalType.getIdentifier()).setPayload(ByteString.copyFrom(((UnknownLogicalType)logicalType).getPayload())).setRepresentation(fieldTypeToProto(logicalType.getBaseType(),serializeLogicalType));
if (logicalType.getArgumentType() != null) {
logicalTypeBuilder.setArgumentType(fieldTypeToProto(logicalType.getArgumentType(),serializeLogicalType)).setArgument(fieldValueToProto(logicalType.getArgumentType(),logicalType.getArgument()));
}
}
 else {
String urn=identifier.startsWith("beam:logical_type:") ? identifier : URN_BEAM_LOGICAL_JAVASDK;
logicalTypeBuilder=SchemaApi.LogicalType.newBuilder().setRepresentation(fieldTypeToProto(logicalType.getBaseType(),serializeLogicalType)).setUrn(urn);
if (logicalType.getArgumentType() != null) {
logicalTypeBuilder=logicalTypeBuilder.setArgumentType(fieldTypeToProto(logicalType.getArgumentType(),serializeLogicalType)).setArgument(fieldValueToProto(logicalType.getArgumentType(),logicalType.getArgument()));
}
if (!isStandard && serializeLogicalType) {
logicalTypeBuilder=logicalTypeBuilder.setPayload(ByteString.copyFrom(SerializableUtils.serializeToByteArray(logicalType)));
}
}
builder.setLogicalType(logicalTypeBuilder.build());
break;
case DATETIME:builder.setLogicalType(SchemaApi.LogicalType.newBuilder().setUrn(URN_BEAM_LOGICAL_MILLIS_INSTANT).setRepresentation(fieldTypeToProto(FieldType.INT64,serializeLogicalType)).build());
break;
case DECIMAL:builder.setLogicalType(SchemaApi.LogicalType.newBuilder().setUrn(URN_BEAM_LOGICAL_DECIMAL).setRepresentation(fieldTypeToProto(FieldType.BYTES,serializeLogicalType)).build());
break;
case BYTE:builder.setAtomicType(SchemaApi.AtomicType.BYTE);
break;
case INT16:builder.setAtomicType(SchemaApi.AtomicType.INT16);
break;
case INT32:builder.setAtomicType(SchemaApi.AtomicType.INT32);
break;
case INT64:builder.setAtomicType(SchemaApi.AtomicType.INT64);
break;
case FLOAT:builder.setAtomicType(SchemaApi.AtomicType.FLOAT);
break;
case DOUBLE:builder.setAtomicType(SchemaApi.AtomicType.DOUBLE);
break;
case STRING:builder.setAtomicType(SchemaApi.AtomicType.STRING);
break;
case BOOLEAN:builder.setAtomicType(SchemaApi.AtomicType.BOOLEAN);
break;
case BYTES:builder.setAtomicType(SchemaApi.AtomicType.BYTES);
break;
}
builder.setNullable(fieldType.getNullable());
return builder.build();
}
